import numpy as np
import pandas as pd
import math

# Helper: return either a scalar-like repr or the exception name/message.
def eval_expr(fn):
    try:
        v = fn()
        # Normalize common pandas scalars for stable comparisons.
        if isinstance(v, (np.generic,)):
            return (str(type(v)), str(v))
        # Timedelta/NaT formatting
        if isinstance(v, pd.Timedelta):
            return ('Timedelta', str(v))
        if v is pd.NaT:
            return ('NaT', 'NaT')
        if isinstance(v, pd.Series):
            # store dtype and values as strings
            return ('Series', str(v.dtype), [None if x is pd.NaT else str(x) for x in v.tolist()])
        if isinstance(v, (list, tuple)):
            return ('list', [str(x) for x in v])
        return (type(v).__name__, str(v))
    except Exception as e:
        return ('Exception', type(e).__name__, str(e))

axis_cases = [0, 1]

results = {}

results['expr_1_series_253_plus_1_sum_value'] = eval_expr(lambda: pd.Series([pd.Timedelta(2**53 + 1, 'ns'), pd.Timedelta(0, 'ns')]).sum()._value)

# DataFrame sum: store both axis results

def df_sum_axis(axis):
    arr = np.array([2**53 + 1, 0], dtype='m8[ns]')
    df = pd.DataFrame({'a': arr, 'b': arr[::-1]})
    return df.sum(axis=axis)

for ax in axis_cases:
    results[f'expr_2_df_sum_axis_{ax}'] = eval_expr(lambda ax=ax: df_sum_axis(ax))

results['expr_3_series_timedelta_min_sum'] = eval_expr(lambda: pd.Series([pd.Timedelta.min]).sum())

results['expr_4_series_rounding_cancellation'] = eval_expr(lambda: pd.Series([pd.Timedelta(2**62 + 1, 'ns'), pd.Timedelta(-(2**62), 'ns')]).sum())

results['expr_5_series_min_and_-1_expect_overflow'] = eval_expr(lambda: pd.Series([pd.Timedelta.min, pd.Timedelta(-1, 'ns')]).sum())

# skipna=False exempt slices: DataFrame sum with NaT under skipna=False should not raise; value for NaT-containing slice is NaT.

def df_sum_skipna_false_axis(axis):
    df = pd.DataFrame({'a': [pd.Timedelta(1,'ns'), pd.Timedelta(2,'ns')],
                       'b': [pd.Timedelta.max, pd.NaT]})
    return df.sum(axis=axis, skipna=False)

for ax in axis_cases:
    results[f'expr_6_df_sum_skipna_false_axis_{ax}'] = eval_expr(lambda ax=ax: df_sum_skipna_false_axis(ax))

results['expr_7_series_max_nat_max_skipna_false'] = eval_expr(lambda: pd.Series([pd.Timedelta.max, pd.NaT, pd.Timedelta.max]).sum(skipna=False))

results['expr_8_series_max_twice_min_count5'] = eval_expr(lambda: pd.Series([pd.Timedelta.max] * 2).sum(min_count=5))

probe(results)

